940	        float dq = 0.0f, dk = 0.0f;
941	        #pragma unroll
942	        for (int kj = 0; kj < dec::kSeq; ++kj) {
943	            dq += ds[pos * dec::kSeq + kj] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + dec::kD + qoff + t]);
944	            dk += ds[kj * dec::kSeq + pos] * __bfloat162float(qkv[(int64_t)(rbase + kj) * 3 * dec::kD + qoff + t]);
945	        }
946	        dqkv_out[(int64_t)(rbase + pos) * 3 * dec::kD + qoff + t] = dq;             // dq block
947	        dqkv_out[(int64_t)(rbase + pos) * 3 * dec::kD + dec::kD + qoff + t] = dk;   // dk block
948	    }
949	    __syncthreads();
950	}
951	
952	// ════════════════════════════════════════════════════════════════════════
953	//  BACKWARD over one TOKEN TILE. Assumes dectc_forward_tile ran for THIS tile
954	//  (scratch + DecActs X-inputs populated). Fork B: computes dX via wgmma and
955	//  WRITES the dY output-adjoints to DecActs (dY_qkv/dY_a/dY_ff0/dY_ff2/
956	//  dY_logits) + dh0 for P2's output-stationary dW — it does NOT touch the
957	//  weight dW here. ACCUMULATES the 10 LN-vector grads (γ/β) into the per-CTA
958	//  LN-vec partials `lnvec` [kNumLnVec × d] (deterministic single-owner-per-j).
959	//  `B` is the full batch (CE mean scale). Mirrors dec_backward_sample.
960	//
961	//  dqkv/dctx/dgact intermediates use the fp32 `work` buffer + a second fp32
962	//  buffer `work2` (caller passes both, each [nrows×dff]); dh (running adjoint)
963	//  is the dedicated scratch.dh.
964	// ════════════════════════════════════════════════════════════════════════
965	__device__ void dectc_backward_tile(
966	        const DecWeights& w, int g0, int nrows, int B, const DecActs& acts,
967	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
968	        float* __restrict__ lnvec, float* __restrict__ work2,
969	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
970	    const int nsamp = nrows / dec::kSeq;
971	    // LN-vec partial slots (dense order; see kLnVecTensorIdx).
972	    float* gn_n1w[dec::kLayers]; float* gn_n1b[dec::kLayers];
973	    float* gn_n2w[dec::kLayers]; float* gn_n2b[dec::kLayers];
974	    for (int li = 0; li < dec::kLayers; ++li) {
975	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * dec::kD;
976	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * dec::kD;
977	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * dec::kD;
978	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * dec::kD;
979	    }
980	    float* gn_normw = lnvec + (int64_t)8 * dec::kD;
981	    float* gn_normb = lnvec + (int64_t)9 * dec::kD;
982	
983	    // ── CE bwd (per sample): dlogits = (softmax - onehot)/B, overwrite logits.
984	    //    head bwd: dY_logits[si] = dlogits (the head dW operand); dhn = dlogits@out_w.
985	    //    final-norm bwd: dh_last (last position only) → scratch.dh (zero others). ──
986	    // First zero scratch.dh for the whole tile (only last positions get grad).
987	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
988	    __syncthreads();
989	    for (int si = 0; si < nsamp; ++si) {
990	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
991	        const int gs = si_global(g0, si);
992	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
993	        int tgt = tgt_ids[gs];
994	        // softmax of cached logits.
995	        float lmax = -CUDART_INF_F;
996	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
997	        lmax = dec_block_max(lmax, red);
998	        float es = 0.0f;
999	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
1000	        es = dec_block_sum(es, red);
1001	        float inv_es = 1.0f / es;
1002	        // dlogits → overwrite lg, AND write to dY_logits[gs] (bf16, head dW operand).
1003	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
1004	            float smo = __expf(lg[o] - lmax) * inv_es;
1005	            float dl = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
1006	            lg[o] = dl;
1007	            acts.dY_logits[(int64_t)gs * dec::kVocab + o] = __float2bfloat16(dl);
1008	        }
1009	        __syncthreads();
1010	        // dhn[j] = Σ_o dlogits[o] * out_w[o,j]  (head dX), feature-parallel → dh row rlast.
1011	        // Then final-norm bwd of that single row → scratch.dh[rlast].
1012	        // Use fnx cache (xhat) + fni (inv). Accumulate norm γ/β. (head dW is P2.)
1013	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1014	            float dhn = 0.0f;
1015	            for (int o = 0; o < dec::kVocab; ++o)
1016	                dhn += lg[o] * w.out_w[(int64_t)o * dec::kD + j];
1017	            // final-norm bwd needs the row-reduce of dxhat; stash dhn into work row rlast.
1018	            sc.work[(int64_t)rlast * dec::kD + j] = dhn;
1019	        }
1020	        __syncthreads();
1021	        // norm γ/β: dnorm_w[j] += dhn*xhat; dnorm_b[j] += dhn. (Only last pos contributes.)
1022	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1023	            float dhn = sc.work[(int64_t)rlast * dec::kD + j];
1024	            float xh = sc.fnx[(int64_t)rlast * dec::kD + j];
1025	            gn_normw[j] += dhn * xh; gn_normb[j] += dhn;
1026	        }
1027	        __syncthreads();
1028	        // LN dx (single row): dxhat=dhn*norm_w; reduce; dh[rlast] = inv*(dxhat-(sda+xhat*sdax)/d).
1029	        {
1030	            const float* dyr = sc.work + (int64_t)rlast * dec::kD;
1031	            const float* xhr = sc.fnx + (int64_t)rlast * dec::kD;
1032	            float sda = 0.0f, sdax = 0.0f;
1033	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1034	                float dxhat = dyr[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xhr[j];
1035	            }
1036	            sda = dec_block_sum(sda, red); sdax = dec_block_sum(sdax, red);
1037	            float iv = sc.fni[rlast];
1038	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1039	                float dxhat = dyr[j] * w.norm_w[j];
1040	                sc.dh[(int64_t)rlast * dec::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
1041	            }
1042	            __syncthreads();
1043	        }
1044	    }
1045	    // scratch.dh now = grad wrt last-layer output [nrows,d] (only last positions nonzero).
1046	
1047	    // ── per-layer backward (reverse). dh is the running adjoint (grad wrt the
1048	    //    layer's n2 output). All fwd intermediates are in scratch/DecActs (NO
1049	    //    recompute). ──
1050	    for (int li = dec::kLayers - 1; li >= 0; --li) {
1051	        const DecWeights::Layer& L = w.layer[li];
1052	        // n2 bwd: dh → dr2 (work fp32), accumulate n2 γ/β. xhat=n2x[li], inv=n2i[li].
1053	        dectc_ln_bwd_tile(sc.dh, sc.n2x[li], sc.n2i[li], L.n2_w, nrows, sc.work, gn_n2w[li], gn_n2b[li], red);
1054	        // r2 = x1 + ff2 → dx1 = dr2 (residual), dff2 = dr2. dff2 → dY_ff2 acts (bf16).
1055	        // dx1 starts as dr2 (copy into work2), the FFN path adds to it.
1056	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1057	            work2[idx] = sc.work[idx];   // dx1 := dr2 (residual part)
1058	            acts.dY_ff2[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // dff2
1059	        }
1060	        __syncthreads();
1061	        // ff2 dX: dgact = dff2 @ ff2_w  (N=dff, K=d). fp32 → tw? need a [nrows,dff] buffer.
1062	        //   Use sc.work (currently dr2, no longer needed — dx1 saved in work2, dff2 in acts).
1063	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff2[li] + (int64_t)g0 * dec::kD, L.ff2_w,
1064	                                           sc.work, dec::kDff, dec::kD, sA, sB);  // dgact [nrows,dff]
1065	        __syncthreads();
1066	        // dff0 = dgact * gelu'(ff0pre) → dY_ff0 acts (bf16) AND keep fp32 in sc.work for dX.
1067	        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
1068	            float dff0 = sc.work[idx] * dec_gelu_grad(__bfloat162float(sc.ff0pre[li][idx]));
1069	            sc.work[idx] = dff0;
1070	            acts.dY_ff0[li][(int64_t)g0 * dec::kDff + idx] = __float2bfloat16(dff0);
1071	        }
1072	        __syncthreads();
1073	        // ff0 dX: dx1 += dff0 @ ff0_w  (output width Kin=d, contract Nout=dff). fp32
1074	        //   → sc.x1 (free now — fwd x1 consumed); then add to work2.
1075	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff0[li] + (int64_t)g0 * dec::kDff, L.ff0_w,
1076	                                           sc.x1, /*Kin=*/dec::kD, /*Nout=*/dec::kDff, sA, sB);  // dx1_ffn [nrows,d]
1077	        __syncthreads();
1078	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1079	            work2[idx] += sc.x1[idx];   // dx1 = residual + FFN path
1080	        __syncthreads();
1081	        // n1 bwd: dx1 (work2) → dr1 (work), accumulate n1 γ/β. xhat=n1x[li], inv=n1i[li].
1082	        dectc_ln_bwd_tile(work2, sc.n1x[li], sc.n1i[li], L.n1_w, nrows, sc.work, gn_n1w[li], gn_n1b[li], red);
1083	        // r1 = x_in + a → da = dr1 (out_proj output adjoint), dx_in = dr1 (residual).
1084	        // SAVE the residual dr1 into sc.dh NOW (dh is free — its grad was consumed into
1085	        // dr2 at the top of this layer); attention bwd will overwrite work2. Then add the
1086	        // in_proj dX path to it. da → dY_a acts (bf16, out_proj dW operand).
1087	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1088	            sc.dh[idx] = sc.work[idx];   // residual dx_in := dr1  (saved across attn bwd)
1089	            acts.dY_a[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // da
1090	        }
1091	        __syncthreads();
1092	        // out_proj dX: dctx = da @ out_w  (N=d, K=d). fp32 → sc.work (dctx [nrows,d]).
1093	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * dec::kD, L.out_w,
1094	                                           sc.work, dec::kD, dec::kD, sA, sB);  // dctx
1095	        __syncthreads();
1096	        // attention bwd: (qkv[li], attn[li], dctx=work) → dqkv [nrows,3d] fp32 into
1097	        //   work2 (3d=384 ≤ dff=512, fits). Then → dY_qkv acts (bf16, in_proj dW operand).
1098	        dectc_attn_bwd_tile(sc.qkv[li], sc.attn[li], sc.work, nrows, work2, sc.dsc);
1099	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x)
1100	            acts.dY_qkv[li][(int64_t)g0 * 3 * dec::kD + idx] = __float2bfloat16(work2[idx]);
1101	        __syncthreads();
1102	        // in_proj dX: dx_in_attn = dqkv @ in_w  (output width Kin=d, contract Nout=3d).
1103	        //   fp32 → sc.work; ADD residual (in sc.dh) → new running adjoint dh.
1104	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_qkv[li] + (int64_t)g0 * 3 * dec::kD, L.in_w,
1105	                                           sc.work, /*Kin=*/dec::kD, /*Nout=*/3 * dec::kD, sA, sB);  // dx_in_attn
1106	        __syncthreads();
1107	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1108	            sc.dh[idx] += sc.work[idx];   // dx_in = residual (in dh) + attn path
1109	        __syncthreads();
1110	    }
1111	
1112	    // ── embedding bwd: dh = grad wrt h0 [nrows,d]. Write dh0 acts (bf16); the
1113	    //    tok/pos owner-scan (P2) reads dh0 by global token row. ──
1114	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1115	        acts.dh0[(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.dh[idx]);
1116	    __syncthreads();
1117	}
1118	
1119	// ════════════════════════════════════════════════════════════════════════
1120	//  P2 — OUTPUT-STATIONARY dW (the Q2 deliverable). Each of the 9 weight
1121	//  matrices dW = dYᵀ @ X (K=T) is split into 64×N output tiles; tile_id %
1122	//  nCTA owns each (fixed every step → determinism + L2 warmth). The owner CTA
1123	//  contracts the FULL token dimension itself (ascending-t, no float atomics, no
1124	//  partials) via the validated dW orientation (tc_gemm_block_unpipelined with
1125	//  BOTH operands transposed-staged, MaxAtomsM=1 → one 64×N tile, 64 acc regs/
1126	//  thread, no spill). Writes the tile into `grad` (the reduced-grad output).
1127	//
1128	//  The 9 weights, in dec_layout tensor-index order, with their (dY,X) acts and

1128	//  The 9 weights, in dec_layout tensor-index order, with their (dY,X) acts and
1129	//  the contraction length K (T for per-position weights, B for the head).
1130	// ════════════════════════════════════════════════════════════════════════
1131	struct DecDwSpec {
1132	    const __nv_bfloat16* dY;   // [K, Nout]
1133	    const __nv_bfloat16* X;    // [K, Kin]
1134	    int Nout; int Kin; int K;
1135	    int grad_off;              // element offset of this weight in `grad`
1136	    const __nv_bfloat16* dY_bias;  // same as dY (bias db = Σ_K dY)
1137	    int bias_off;              // element offset of the bias in `grad`
1138	};
1139	
1140	// Build the 9 specs (called by all CTAs; cheap). T = B*kSeq.
1141	__device__ __forceinline__ void dectc_build_dw_specs(
1142	        const DecActs& acts, int B, int T, DecDwSpec spec[9]) {
1143	    // dec_layout offsets: see kDecOffsets. Weight tensor indices (and bias idx):
1144	    //   L0: in_w=2 (in_b=3), out_w=4 (out_b=5), ff0_w=10 (ff0_b=11), ff2_w=12 (ff2_b=13)
1145	    //   L1: in_w=14(15), out_w=16(17), ff0_w=22(23), ff2_w=24(25)
1146	    //   head: out_w=28 (out_b=29)
1147	    const int wi[9]  = {2,4,10,12, 14,16,22,24, 28};
1148	    const int bi[9]  = {3,5,11,13, 15,17,23,25, 29};
1149	    for (int s = 0; s < 8; ++s) {
1150	        const int li = s / 4, kind = s % 4;
1151	        DecDwSpec& sp = spec[s];
1152	        sp.K = T; sp.grad_off = kDecOffsets[wi[s]]; sp.bias_off = kDecOffsets[bi[s]];
1153	        if (kind == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * dec::kD; sp.Kin = dec::kD;   }
1154	        else if (kind == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = dec::kD;     sp.Kin = dec::kD;   }
1155	        else if (kind == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = dec::kDff;   sp.Kin = dec::kD;   }
1156	        else                { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = dec::kD;     sp.Kin = dec::kDff; }
1157	        sp.dY_bias = sp.dY;
1158	    }
1159	    DecDwSpec& hd = spec[8];
1160	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = dec::kVocab; hd.Kin = dec::kD; hd.K = B;
1161	    hd.grad_off = kDecOffsets[28]; hd.bias_off = kDecOffsets[29]; hd.dY_bias = hd.dY;
1162	}
1163	
1164	// ── dW M-atom INTERLEAVE group width (task #13 H3). A dW output "tile" (work
1165	//    item) owns a GROUP of up to kDecDwIL consecutive m64 atoms instead of one,
1166	//    so the engine runs kDecDwIL wgmmas/k-step into independent fragments sharing
1167	//    ONE staged X (B-operand) tile → the H1 win (overlap the MMAs + kDecDwIL× less
1168	//    X-operand HBM traffic) now applies to the dW K=T contraction (the post-H2
1169	//    dominant phase). kDecDwIL == the engine's interleave cap kDecMaxIL so the
1170	//    ring smem (DecTcSmem.sA, sized kDecAtomsPerSlot=min(kAtomsM,kDecMaxIL) A-tiles
1171	//    per slot) and the selftest-validated dW path (gemm_dw_kernel: MaxAtomsM=8,
1172	//    kIL=min(8,2)=2) match exactly. Ascending-k per atom is unchanged → numerics
1173	//    bit-identical + A/A/A determinism. Atoms-per-weight-N-tile / groups: ──
1174	constexpr int kDecDwIL = kDecMaxIL;
1175	__device__ __host__ __forceinline__ int dec_dw_atoms(int Nout)  { return (Nout + 63) / 64; }
1176	__device__ __host__ __forceinline__ int dec_dw_groups(int Nout) {
1177	    return (dec_dw_atoms(Nout) + kDecDwIL - 1) / kDecDwIL;
1178	}
1179	
1180	// Total number of dW output WORK ITEMS (M-atom groups × N-tiles) across the 9
1181	// weights (the tile loop count). Each item is a group of <= kDecDwIL m64 atoms.
1182	template <int N>
1183	__device__ __forceinline__ int dectc_dw_total_tiles(const DecDwSpec spec[9]) {
1184	    int n = 0;
1185	    for (int s = 0; s < 9; ++s)
1186	        n += dec_dw_groups(spec[s].Nout) * ((spec[s].Kin + N - 1) / N);
1187	    return n;
1188	}
1189	
1190	// Run ONE global dW work item `gt` (if it belongs to this CTA): decode (weight,
1191	// M-atom GROUP, N-tile), then contract K via the dW GEMM into grad[grad_off]. The
1192	// group is up to kDecDwIL stacked m64 atoms → the engine interleaves them (kIL=
1193	// kDecDwIL): kDecDwIL wgmmas/k-step into independent fragments sharing ONE staged
1194	// X B-tile (H1's win, now on the dW K=T contraction).
1195	template <int N>
1196	__device__ __forceinline__ void dectc_dw_run_tile(
1197	        const DecDwSpec spec[9], int gt, float* __restrict__ grad,
1198	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1199	    // Decode gt → (s, m_group, n_tile).
1200	    int acc = 0, s = 0, m_group = 0, n_tile = 0;
1201	    for (s = 0; s < 9; ++s) {
1202	        const int ng = dec_dw_groups(spec[s].Nout);
1203	        const int nt = (spec[s].Kin + N - 1) / N;
1204	        if (gt < acc + ng * nt) { int loc = gt - acc; m_group = loc / nt; n_tile = loc % nt; break; }
1205	        acc += ng * nt;
1206	    }
1207	    const DecDwSpec& sp = spec[s];
1208	    const int n_atoms = dec_dw_atoms(sp.Nout);
1209	    const int a0 = m_group * kDecDwIL;               // first atom of the group
1210	    const int g_atoms = (n_atoms - a0) < kDecDwIL ? (n_atoms - a0) : kDecDwIL;
1211	    const int mbase = a0 * 64;
1212	    const int n0 = n_tile * N;
1213	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1214	    const int k_steps = sp.K / wgs::kWgmmaAtomK;     // K = T or B (must be /16; padded by caller)
1215	    const int Nout = sp.Nout, Kin = sp.Kin;
1216	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1217	    // The engine (tc_gemm_block_unpipelined, mbase0=mbase) passes the GLOBAL row
1218	    // m = mbase + (group-local row) to srcA/out (it adds mbase0 itself), so the
1219	    // accessors use `m` RAW — adding mbase again would double-count (the selftest
1220	    // gemm_dw_kernel passes mbase0=0, m_atoms=all, and uses m raw; we shard the
1221	    // atoms into groups, pass mbase0=mbase, and likewise use m raw).
1222	    // A[m=out, k=t] = dY[t,out]  (transposed read); B[n=in, k=t] = X[t,in] (transposed).
1223	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1224	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
1225	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1226	        int nn = n0 + n; return nn < Kin ? X[(int64_t)k * Kin + nn] : __float2bfloat16(0.f); };
1227	    auto out  = [&] (int m, int n, float v) {
1228	        if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
1229	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kDecDwIL>(
1230	        mbase, g_atoms, n_real, k_steps, srcA, srcB, out, sA, sB);
1231	}
1232	
1233	// ════════════════════════════════════════════════════════════════════════
1234	//  SPLIT-K dW (multi-CTA tiling — the validated mamba fix). The 9 dW yield only
1235	//  ~50 output tiles → ~62% of 132 SMs idle in P2. Split-K turns each output tile
1236	//  into G work items (one per K-chunk), so the grid sees (n_dw·G) items → idle
1237	//  SMs do work. Each CTA computes a PARTIAL over its K-chunk into a per-(tile,
1238	//  chunk) scratch slot; a grid barrier; then a DETERMINISTIC ascending-chunk
1239	//  reduce sums the G partials into grad — no float atomics, fixed order, so
1240	//  parity + A/A/A bit-determinism hold (each partial is the SAME ascending-k fp32
1241	//  wgmma accumulate; Σ_chunk == full-K sum reassociated into G fp32 blocks).
1242	//  G==1 routes to the single-CTA dectc_dw_run_tile above (no scratch). Slot (gt,
1243	//  kc) at dw_part[((gt*G+kc)) * (kDecDwIL·64·kDecMaxTileN) + lr*kDecMaxTileN + col]
1244	//  — each work item gt is an M-atom GROUP (up to kDecDwIL=2 stacked m64 atoms, H3),
1245	//  so its slot holds kDecDwIL·64 group-local rows (lr). Decoder K varies per spec:
1246	//  layer dW K=T, head dW K=B (so kc_steps reads sp.K).
1247	// ════════════════════════════════════════════════════════════════════════
1248	constexpr int kDecMaxTileN = SG_TUNED_TILE_N;                       // widest dW N-tile
1249	// Floats per (gt,kc) split-K slot: a work item is an M-atom GROUP of up to kDecDwIL
1250	// stacked m64 atoms → kDecDwIL·64 rows × N cols. (Was 64·N for the 1-atom item.)
1251	constexpr int kDecDwTileFloats = kDecDwIL * wgs::kWgmmaAtomM * kDecMaxTileN;
1252	
1253	// COMPILE-TIME max #dW output WORK ITEMS (the 9 dW have fixed Nout/Kin; decoder
1254	// dims are compile-time → constant). per layer: qkv(3d×d), attn_out(d×d), ff0(dff
1255	// ×d), ff2(d×dff), N=kDecMaxTileN; + head(V×d). The M factor is now M-atom GROUPS
1256	// of kDecDwIL (ceil(atoms/kDecDwIL)), matching dec_dw_groups — NOT single atoms.
1257	constexpr int kDecDwMGroups(int Nout) {                 // ceil(ceil(Nout/64)/kDecDwIL)
1258	    return (((Nout + 63) / 64) + kDecDwIL - 1) / kDecDwIL;
1259	}
1260	constexpr int kDecDwTilesPerLayer =
1261	      kDecDwMGroups(3*dec::kD) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // qkv
1262	    + kDecDwMGroups(dec::kD)   * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // attn_out
1263	    + kDecDwMGroups(dec::kDff) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // ff0
1264	    + kDecDwMGroups(dec::kD)   * ((dec::kDff+ kDecMaxTileN - 1)/kDecMaxTileN);  // ff2
1265	constexpr int kDecDwHeadTiles =
1266	      kDecDwMGroups(dec::kVocab) * ((dec::kD + kDecMaxTileN - 1)/kDecMaxTileN);
1267	constexpr int kDecDwMaxTiles = dec::kLayers * kDecDwTilesPerLayer + kDecDwHeadTiles;
1268	
1269	// Split-K dW partial-scratch float count (host carves it from the workspace tail).
1270	__host__ __device__ __forceinline__ int64_t dec_dw_part_floats(int G) {
1271	    return (int64_t)kDecDwMaxTiles * G * kDecDwTileFloats;
1272	}
1273	
1274	// Decode global dW work-item index gt → (spec index s, m_group, n_tile). Single-
1275	// source: m_group indexes M-atom GROUPS of kDecDwIL (group's first atom = m_group·
1276	// kDecDwIL, base row = m_group·kDecDwIL·64).
1277	template <int N>
1278	__device__ __forceinline__ void dectc_dw_decode(
1279	        const DecDwSpec spec[9], int gt, int& s, int& m_group, int& n_tile) {
1280	    int acc = 0;
1281	    for (s = 0; s < 9; ++s) {
1282	        const int ng = dec_dw_groups(spec[s].Nout);
1283	        const int nt = (spec[s].Kin + N - 1) / N;
1284	        if (gt < acc + ng * nt) { int loc = gt - acc; m_group = loc / nt; n_tile = loc % nt; return; }
1285	        acc += ng * nt;
1286	    }
1287	    s = 8; m_group = 0; n_tile = 0;   // unreachable (gt < n_dw); keep defined
1288	}
1289	
1290	// PARTIAL dW for global tile gt over K-chunk kc of G → dw_part. K-chunk uses sp.K
1291	// (layer T / head B). FLOOR-BALANCED partition: chunk kc = [k0,k1) with
1292	// k0=floor(kc·KS/G), k1=floor((kc+1)·KS/G) — near-equal, summing to KS EXACTLY for
1293	// ANY KS≥G (no `G | KS` requirement → works at the production truncated B=4176,
1294	// where the head's KS=B/16 need NOT be divisible by G). A CEIL split would leave a
1295	// trailing EMPTY chunk whose slot stays unwritten → the reduce sums garbage (the
1296	// determinism-blind dW bug); floor never empties a chunk for KS≥G. Fresh ScaleD=0
1297	// per chunk → true partial. Writes the full 64×N tile (LOCAL rows) to the slot.
1298	template <int N>
1299	__device__ __forceinline__ void dectc_dw_run_tile_splitk(
1300	        const DecDwSpec spec[9], int gt, int kc, int G, float* __restrict__ dw_part,
1301	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1302	    int s, m_group, n_tile;
1303	    dectc_dw_decode<N>(spec, gt, s, m_group, n_tile);
1304	    const DecDwSpec& sp = spec[s];
1305	    const int n_atoms = dec_dw_atoms(sp.Nout);
1306	    const int a0 = m_group * kDecDwIL;                      // first atom of the group
1307	    const int g_atoms = (n_atoms - a0) < kDecDwIL ? (n_atoms - a0) : kDecDwIL;
1308	    const int mbase = a0 * 64;
1309	    const int n0 = n_tile * N;
1310	    const int KS = sp.K / wgs::kWgmmaAtomK;                 // total k-atoms (T/16 or B/16)
1311	    const int k0 = (int)(((int64_t)kc       * KS) / G);     // floor-balanced chunk bounds
1312	    const int k1 = (int)(((int64_t)(kc + 1) * KS) / G);
1313	    const int kc_steps = k1 - k0;                          // sums to KS exactly over kc
1314	    // Slot holds the GROUP's kDecDwIL·64 rows (lr) × N cols (kDecDwTileFloats).
1315	    float* slot = dw_part + ((int64_t)gt * G + kc) * kDecDwTileFloats;
1316	    // Empty-chunk guard (KS<G, i.e. B<64): a k_steps=0 GEMM would emit the
1317	    // uninitialized accumulator → zero the WHOLE group slot + return instead of
1318	    // running it (the reduce sums all G slots unconditionally, so an empty chunk
1319	    // MUST be 0). Zero the full kDecDwIL·64·N slot (only g_atoms·64 rows are valid
1320	    // but the reduce reads only valid rows; zeroing all keeps it simple + safe).
1321	    if (kc_steps <= 0) {
1322	        for (int i = threadIdx.x; i < kDecDwTileFloats; i += blockDim.x) slot[i] = 0.0f;
1323	        __syncthreads();
1324	        return;
1325	    }
1326	    const int Nout = sp.Nout, Kin = sp.Kin;
1327	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1328	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1329	        return m < Nout ? dY[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Nout + m] : __float2bfloat16(0.f); };
1330	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1331	        int nn = n0 + n; return nn < Kin ? X[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Kin + nn] : __float2bfloat16(0.f); };
1332	    // out(mbase+row, col, v): m is GLOBAL (srcA needs it; engine adds mbase0=mbase);
1333	    // the slot holds the GROUP's kDecDwIL·64 LOCAL rows → index by (m - mbase). The
1334	    // engine emits group-local rows in [0, g_atoms·64); writing them by (m-mbase)
1335	    // fills the lower g_atoms·64 rows (a ragged final group's tail rows stay as the
1336	    // zeroed/garbage upper rows but the reduce reads only valid rows → never used).
1337	    auto out  = [&] (int m, int n, float v) {
1338	        const int lr = m - mbase;
1339	        if (lr >= 0 && lr < kDecDwIL * 64 && n < N) slot[(int64_t)lr * N + n] = v; };
1340	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kDecDwIL>(
1341	        mbase, g_atoms, /*n_real=*/N, kc_steps, srcA, srcB, out, sA, sB);
1342	}
1343	
1344	// Deterministic reduce: output tile gt (% nCTA) sums its G chunk-partials ascending-kc
1345	// → grad. Same (gt → geometry) decode as the partial.
1346	template <int N>
1347	__device__ __forceinline__ void dectc_dw_reduce_splitk(
1348	        const DecDwSpec spec[9], int n_dw, int G, const float* __restrict__ dw_part,
1349	        float* __restrict__ grad, int cta, int nCTA) {
1350	    for (int gt = cta; gt < n_dw; gt += nCTA) {
1351	        int s, m_group, n_tile;
1352	        dectc_dw_decode<N>(spec, gt, s, m_group, n_tile);
1353	        const DecDwSpec& sp = spec[s];
1354	        const int mbase = m_group * kDecDwIL * 64;          // group's first global row
1355	        const int n0 = n_tile * N;
1356	        const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1357	        // Valid group rows: up to kDecDwIL·64, clamped to the weight's row count.
1358	        const int grp_rows = kDecDwIL * 64;
1359	        const int Nrow = (sp.Nout - mbase) < grp_rows ? (sp.Nout - mbase) : grp_rows;
1360	        const int64_t base = (int64_t)gt * G * kDecDwTileFloats;
1361	        for (int idx = threadIdx.x; idx < Nrow * n_real; idx += blockDim.x) {
1362	            const int row = idx / n_real, col = idx % n_real;   // row = group-local lr
1363	            float accv = 0.0f;
1364	            for (int kc = 0; kc < G; ++kc)
1365	                accv += dw_part[base + (int64_t)kc * kDecDwTileFloats + (int64_t)row * N + col];
1366	            grad[sp.grad_off + (int64_t)(mbase + row) * sp.Kin + n0 + col] = accv;
1367	        }

            red[threadIdx.x] = tsum;
            __syncthreads();
            for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
                if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
                __syncthreads();
            }
            if (threadIdx.x == 0) sq_part[cta] = red[0];
            bar.sync();   // B2.4a: all per-CTA Σg² partials complete
            if (cta == 0 && threadIdx.x == 0) {
                double ss = 0.0;
                for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
                const float gnorm = sqrtf((float)ss);
                // rho / ‖g‖ (matches bindings.cpp looksam_perturb_all). gnorm>0 in
                // any real training step; guard div-by-0 → 0 (no perturb) to be safe.
                *ron_bc = (gnorm > 0.0f) ? (st.rho / gnorm) : 0.0f;
            }
            bar.sync();   // B2.4b: rho_over_norm broadcast ready
        }
        const float rho_over_norm = *ron_bc;
        // (b) Backup + perturb p in place: p' = p + rho_over_norm·g. Grid-strided
        //     over the flat param vector (each element owned once → no race).
        {
            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
                 i < total; i += gstride) {
                sam_backup[i] = params[i];
                params[i] = params[i] + rho_over_norm * grad[i];
            }
        }
        bar.sync();   // B2.4c: all params perturbed before the 2nd forward reads them
        // (c) SECOND fwd+bwd at the perturbed weights → g_sam in `sam_grad`. Mirror
        //     P1 + P2 EXACTLY, but: re-zero the lnvec partials (they accumulate),
        //     do NOT write the loss (keep the first-pass loss), and assemble into
        //     `sam_grad` (NOT `grad`). `w` wraps `params` (now perturbed) so the
        //     tile fns read the perturbed weights with no re-bind needed.
        for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
        bar.sync();   // B2.4d: lnvec partials cleared before the 2nd backward accumulates
        for (int ti = cta; ti < n_tiles; ti += nCTA) {
            const int g0 = ti * nrows_tile;
            const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
            dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
                                      sm.sA, sm.sB, sm.red);
            dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
                                       my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
            __syncthreads();
        }
        bar.sync();   // B2.4e: all 2nd-pass acts (X + dY) + LN-vec partials complete
        // Re-build the dW specs from the 2nd-pass acts (dY adjoints changed).
        if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
        __syncthreads();
        dectc::DecDwSpec* spec2 = sm.spec;
        const int n_dw2 = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec2);
        if (kDwG > 1) {
            for (int item = cta; item < n_dw2 * kDwG; item += nCTA) {
                const int gt = item / kDwG, kc = item % kDwG;
                dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec2, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
            }
            bar.sync();
            dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec2, n_dw2, kDwG, dw_part, sam_grad, cta, nCTA);
        } else {
            for (int gt = cta; gt < n_dw2; gt += nCTA)
                dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec2, gt, sam_grad, sm.sA, sm.sB);
        }
        dectc::dectc_dw_biases(spec2, sam_grad, cta, nCTA);
        // Reuse the P1-built token lists: the SAM 2nd pass perturbs WEIGHTS, not
        // tok_ids, so the token→row mapping (row_start/perm) is unchanged.
        dectc::dectc_embed_owner_scan(acts, embed_row_start, embed_perm, T, sam_grad, cta, nCTA);
        dectc::dectc_lnvec_reduce(lnvec_base, sam_grad, nCTA, cta);
        bar.sync();   // B2.4f: g_sam fully assembled in sam_grad
        // (d) WRITE the SAM side-channel (into the persistent state slice) + restore p.
        //     LookSAM → sam_dir = g_sam − g; SuperGrok11/15/SuperGrok2 → sharpness =
        //     (g_sam − g)² (SG2 shares the SAM 2nd-backward machinery: its meta-net's
        //     2nd MLP input is the SAME sharpness signal, read by sg2_meta_stages).
        {
            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
                 i < total; i += gstride) {
                const float diff = sam_grad[i] - grad[i];
                if constexpr (Opt == OptId::LookSAM) {
                    // st.sam_dir is the extra-slice base (host-bound). g_sam − g.
                    const_cast<float*>(st.sam_dir)[i] = diff;
                } else {
                    // SuperGrok11/15/SuperGrok2: sharpness = (g_sam − g)² (state slice).
                    const_cast<float*>(st.sharpness)[i] = diff * diff;
                }
                params[i] = sam_backup[i];   // restore the ORIGINAL weights
            }
        }
        bar.sync_reset(ctx.g_next_task);   // B2.4g: params restored + side-channel ready; reset queue for P3
    }
}

// ── P2.5 (GrokAdamW ONLY): GLOBAL grad-norm clip coefficient. Eager
//    grokadamw clips the WHOLE grad set to grad_clip via a GLOBAL L2 norm
//    (clip_grad_norms_device_side → total_norm = sqrt(Σ_i ‖g_i‖²),
//    clip_coef = grad_clip/(total_norm+1e-6) when total_norm>grad_clip,
//    else 1) BEFORE the apply. We replicate it on the REDUCED grad with a
//    deterministic ascending reduction (no float atomics): each CTA sums a
//    contiguous element-range into a per-CTA partial slot, CTA0 sums the
//    partials in ascending CTA order → total_norm → clip_coef, broadcast via
//    a workspace slot. The grad buffer is NOT mutated (the return_grad oracle
//    + the eager-side clip must both see the unclipped reduced grad); the
//    coefficient is applied per-element inside apply_optimizer<GrokAdamW>.
//    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
if constexpr (Opt == OptId::GrokAdamW) {
    // Reuse the (now-consumed) loss workspace: loss_part[nCTA] holds per-CTA
    // partial sum-of-squares; loss_out (1 float) broadcasts clip_coef. The
    // reduced loss is already in *tok.loss_out (state), so this is free scratch.
    float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
    float* coef_bc = loss_out;           // [1] broadcast clip_coef
    // Per-CTA contiguous element range over `grad` (the reduced grad, [total]).
    const int64_t total = kDecTotalElems;
    const int64_t base = total / nCTA, rem = total % nCTA;
    const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
    const int64_t ecnt = base + (cta < rem ? 1 : 0);
    // Thread-local partial → block reduce (fixed tree) → thread0 writes the slot.
    float tsum = 0.0f;
    for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
        const float gv = grad[e0 + i];
        tsum += gv * gv;
    }
    // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
    float* red = sm.red;
    red[threadIdx.x] = tsum;
    __syncthreads();
    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
        __syncthreads();
    }
    if (threadIdx.x == 0) sq_part[cta] = red[0];
    bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete

    return p;
}
// The dec_layout tensor index for each partial slot, in P2 reduce order. Built at
// runtime in the reduce (functions of li) — see mbtc_partial_reduce.

// ════════════════════════════════════════════════════════════════════════
//  FORWARD over one SAMPLE TILE (nsamp = nrows/kSeq samples, kTileM rows), global
//  token rows [g0, g0+nrows). The 4 PROJECTIONS run tile-wide on wgmma (M=nrows);
//  conv1d / selective-scan / gate / skip / LN / head / CE run PER-SAMPLE scalar
//  (REUSING model_stage_mamba3.cuh's mb_conv1d_fwd / mb_scan_fwd / mb_layernorm_fwd
//  verbatim with a = &act[li][si]). Writes the MbActs projection operands (bf16)
//  + the per-(layer,sample) LayerAct caches the bwd reads; returns the tile's
//  summed NLL (thread 0 holds it). tok_ids/tgt_ids are HBM int32.
//
//  Mirrors mb_forward_sample's math EXACTLY; the precision fork: layer_in bf16
//  (in_proj + residual), x_main/dt_raw fp32 into scan/conv/gate with ONLY the
//  bf16 copy consumed by x_proj/dt_proj rounded; LN/scan/conv/gate/head fp32.
// ════════════════════════════════════════════════════════════════════════
// __noinline__ (mirrors mbtc_backward_tile): one shared out-of-line frame for the
// 2nd-pass cells that call the forward twice, bounding the megakernel's register
// footprint so the wgmma accumulator stays register-resident (A/A/A determinism).
__device__ __noinline__ float mbtc_forward_tile(
        const MambaWeights& w, int g0, int nrows, const MbActs& acts,
        const MbTileScratch& sc, const int* __restrict__ tok_ids,
        const int* __restrict__ tgt_ids,
        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
    const int nsamp = nrows / mb::kSeq;
    // ── Embedding: X_in[0][g] = tok[id] + pos[s%S]. bf16. ──
    for (int idx = threadIdx.x; idx < nrows * mb::kD; idx += blockDim.x) {
        const int r = idx / mb::kD, j = idx % mb::kD;
        const int g = g0 + r;
        const int tid = tok_ids[g];
        const int sp = g % mb::kSeq;
        float v = w.tok[(int64_t)tid * mb::kD + j] + w.pos[(int64_t)sp * mb::kD + j];
        acts.X_in[0][(int64_t)g * mb::kD + j] = __float2bfloat16(v);
    }
//  BACKWARD over one SAMPLE TILE. Assumes mbtc_forward_tile ran for THIS tile
//  (act caches + final/fn caches + logits populated). The 4 PROJECTIONS compute
//  dX via wgmma and WRITE the dY output-adjoints to MbActs (dY_dxz/dY_dxdbc/
//  dY_ddtpre/dY_dyout) + dh0 for P2's output-stationary dW (it does NOT touch the
//  proj dW here). The scan/conv (per-sample scalar, REUSED mb_scan_bwd /
//  mb_conv1d_bwd) + the gate/skip + LN + scalar head accumulate A_log/D/conv_w/b/
//  n_w/b/norm/out into the per-CTA partial `part`. `B` is the full batch (CE mean).
//  Mirrors mb_backward_sample's order 1..13 exactly.
//
//  smem: `dBmat_s`/`dCmat_s` [kSeq*kState] each (the scan-bwd cross-channel reduce
//  target, zeroed + consumed PER SAMPLE). `red` the reduction slot.
// ════════════════════════════════════════════════════════════════════════
// __noinline__ (A/A/A DETERMINISM, register-pressure bound): the megakernel calls
// this heavy backward from P1 AND — for the SAM-2nd-pass cells (looksam/SG) — a
// SECOND time inside the P2.4 SAM block. Inlining both copies into the megakernel
// pushes the per-thread frame past the wgmma-accumulator-spill threshold (the
// LookSAM instantiation hit STACK 3024 / spilled the 64-reg wgmma accumulator of
// the projection GEMMs in the double-buffer window → non-deterministic denormal/NaN
// grad drift; the basic single-pass cells stayed under it). Forcing ONE shared
// out-of-line frame keeps the megakernel's own register footprint small for EVERY
