        const int64_t r = i % kWbfLayerElems;
        int wi; int64_t off;
        if      (r < kWbfInW)                       { wi = 2;  off = r; }
        else if (r < kWbfInW + kWbfOutW)            { wi = 4;  off = r - kWbfInW; }
