import re, subprocess, collections
txt=open("logs/dec_C1V5.log").read()
pat=re.compile(r"Function properties for (\S+)\n\s*(\d+) bytes stack frame, (\d+) bytes spill stores, (\d+) bytes spill loads")
agg=collections.Counter(); worst={}
for m in pat.finditer(txt):
    name=subprocess.run(["c++filt",m.group(1)],capture_output=True,text=True).stdout.strip()
    short=re.sub(r"<.*","",name.split("(")[0]).split("::")[-1]
    st=int(m.group(3))
    if st>worst.get(short,(0,))[0] if isinstance(worst.get(short),tuple) else st>worst.get(short,0):
        worst[short]=st
    agg[(short,st)]+=1
for (short,st),n in sorted(agg.items(), key=lambda kv:-kv[0][1]):
    if st>0: print(f"{n:3d}x  {short:35s} spill_st={st}")
